package io.github.jesterportfolio.hearth.gathering;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class GatheringContentTest {
    @Test void boxIsBoundedAndTemplateCannotContainContainerOrUnknownMaterial(){assertThrows(IllegalArgumentException.class,()->new GatheringContent.Box(0,0,0,100,100,100));assertThrows(IllegalArgumentException.class,()->new GatheringContent.Box(0,319,0,1,2,1));assertThrows(IllegalArgumentException.class,()->new GatheringContent.Template("test",Map.of(new GatheringContent.Cell(0,64,0),"CHEST")));assertThrows(IllegalArgumentException.class,()->new GatheringContent.Position(Double.NaN,64,0,0,0));}
    @Test void rawWoodSourceIsSupportedWithoutOpeningContainerWhitelist(){var cell=new GatheringContent.Cell(0,64,0);assertEquals("OAK_LOG",new GatheringContent.Template("wood",Map.of(cell,"OAK_LOG")).blocks().get(cell));for(String type:List.of("CHEST","BARREL","FURNACE"))assertThrows(IllegalArgumentException.class,()->new GatheringContent.Template("bad",Map.of(cell,type)));}
    @Test void contentRequiresCompleteTemplateAndOutsideEntrance(){var c=GatheringDungeonTest.content();assertThrows(IllegalArgumentException.class,()->new GatheringContent(c.id(),c.area(),c.spawn(),c.spawn(),1000,100,c.active(),c.templates()));var t=new GatheringContent.Template("partial",Map.of(c.area().cells().getFirst(),"STONE"));assertThrows(IllegalArgumentException.class,()->new GatheringContent(c.id(),c.area(),c.entrance(),c.spawn(),1000,100,t.version(),Map.of(t.version(),t)));}
    @Test void hashDoesNotDependOnMapInsertionOrder(){var c=GatheringDungeonTest.content();var t=c.templates().get(c.active());var reverse=new LinkedHashMap<GatheringContent.Cell,String>();var keys=new ArrayList<>(t.blocks().keySet());Collections.reverse(keys);keys.forEach(k->reverse.put(k,t.blocks().get(k)));assertEquals(t.hash(),new GatheringContent.Template(t.version(),reverse).hash());assertNotEquals(t.hash(),new GatheringContent.Template("version_two",reverse).hash());assertThrows(UnsupportedOperationException.class,()->t.blocks().clear());}
    static Map<String,Object> definition(){var result=new HashMap<String,Object>();result.put("format",1);result.put("isolated-region-prototype",true);result.put("id","demo");result.put("area",Map.of("x",0,"y",63,"z",0,"width",2,"height",3,"depth",2));result.put("entrance",Map.of("x",5,"y",64,"z",5,"yaw",0,"pitch",0));result.put("spawn",Map.of("x",.5,"y",64,"z",.5,"yaw",0,"pitch",0));result.put("interval-ms",2592000000L);result.put("warning-ms",1000);result.put("active-template","v_one");result.put("templates",List.of(Map.of("version","v_one","layers",List.of(Map.of("y",63,"material","STONE")),"blocks",List.of(Map.of("x",1,"y",64,"z",1,"material","IRON_ORE")))));return result;}
    @Test void parsesLongIntervalAndExplicitAirCellsWithoutPublishingOperatingValue(){var c=GatheringContent.parse(definition());assertEquals(2592000000L,c.intervalMillis());assertEquals(12,c.templates().get(c.active()).blocks().size());assertEquals("AIR",c.templates().get(c.active()).blocks().get(new GatheringContent.Cell(0,64,0)));}
    @Test void duplicateVersionOutsideBlocksAndMissingGateAreRejected(){var root=definition();var row=((List<?>)root.get("templates")).getFirst();root.put("templates",List.of(row,row));var duplicate=root;assertThrows(IllegalArgumentException.class,()->GatheringContent.parse(duplicate));var invalid=definition();invalid.put("isolated-region-prototype",false);assertThrows(IllegalArgumentException.class,()->GatheringContent.parse(invalid));var outside=new HashMap<Object,Object>((Map<?,?>)row);outside.put("blocks",List.of(Map.of("x",999,"y",64,"z",0,"material","STONE")));var other=definition();other.put("templates",List.of(outside));assertThrows(IllegalArgumentException.class,()->GatheringContent.parse(other));}
}
